"""Plan prices and coupons (moved over from the old billing monolith)."""

from decimal import Decimal

from .errors import BillingError
from .money import round_money, to_money

PLAN_PRICES = {"starter": 9.99, "team": 49.0, "business": 199.0}
COUPONS = {"WELCOME10": 10, "PARTNER25": 25}

HUNDRED = Decimal("100")


def list_price(plan_code: str) -> float:
    try:
        return PLAN_PRICES[plan_code]
    except KeyError:
        raise ValueError(f"unknown plan {plan_code!r}") from None


def apply_coupon(price: float, coupon: str) -> float:
    if coupon not in COUPONS:
        raise ValueError(f"unknown coupon {coupon!r}")
    return round(price * (100 - COUPONS[coupon]) / 100, 2)


def add_tax(amount, rate_percent):
    """Gross amount including ``rate_percent`` percent tax.

    The tax rate must be between 0 and 100 inclusive. The result is rounded
    to the cent using the finance team's half-up rounding policy.
    """
    if isinstance(rate_percent, bool):
        raise BillingError("invalid_rate", repr(rate_percent))
    try:
        rate = Decimal(str(rate_percent))
    except Exception:
        raise BillingError("invalid_rate", repr(rate_percent)) from None
    if not rate.is_finite() or rate < 0 or rate > HUNDRED:
        raise BillingError("invalid_rate", repr(rate_percent))
    base = to_money(amount)
    return round_money(base * (HUNDRED + rate) / HUNDRED)
EOF
